\title{Sheaf-Theoretic Data Integration:\\ When Databases Form a Sheaf}
\author{Aristotle}
\date{2026-06-18}

\begin{document}
\maketitle

\begin{abstract}
We develop a discrete, elementary theory of data integration in which a database
with missing entries is modeled as a \emph{partial section} of a sheaf over a
grid of (row, column) positions. The sheaf condition---that partial sections
agreeing on their overlaps can be glued into a global section---becomes the exact
condition for consistent imputation of missing data. We give precise definitions
of partial databases, pairwise consistency, gluing, and a discrete
\emph{coboundary norm} measuring total inconsistency across overlapping pairs.
Our central bridge theorem establishes that the coboundary norm vanishes if and
only if the sheaf condition holds, the discrete analogue of $\ker(\delta^0)=H^0$.
We characterize optimal imputation as the vanishing of an imputation objective
(zero cost iff faithful extension), prove that gluing extends both consistent
inputs and preserves consistency with third parties, and introduce a novel
\emph{sheaf filtration} structure modeling progressive imputation, for which
monotonicity automatically implies consistency. Finally, we formulate a
quantitative \emph{consistency probability} model $P=(1-r)^C$ and prove its
monotonicity, multiplicativity, and boundary behavior, leading to a falsifiable
conjecture of exponential consistency decay in the number of overlap constraints.
All results have been formally verified.
\end{abstract}

\section{Introduction}
Missing data is ubiquitous. Classical imputation methods---mean imputation,
$k$-nearest-neighbors (KNN), and multivariate imputation by chained equations
(MICE)---treat completion as statistical prediction, filling each gap with a
plausible value. What they ignore is the \emph{consistency structure} of the
data: when overlapping sources or feature subsets jointly constrain the same
cells, there are global compatibility conditions any honest completion must
respect.

Sheaf theory manages the passage from local to global data. A sheaf assigns to
each open set a set of sections with restriction maps, subject to the gluing
axiom: local sections agreeing on overlaps determine a unique global section.
This is exactly the structure latent in data integration. A partial database is
local data; two sources are compatible when they agree on shared cells; a
complete consistent database is a global section. We make the correspondence
rigorous in an elementary, constructive setting, and prove a self-contained suite
of theorems.

\section{Preliminaries}
Fix $\mathrm{nRows}, \mathrm{nCols} \in \mathbb{N}$ and a value type $V$. A
\emph{position} is a pair $p=(r,c)$ with $r \in \mathrm{Fin}\,\mathrm{nRows}$,
$c \in \mathrm{Fin}\,\mathrm{nCols}$; the position set is
$\mathrm{DBPos} := \mathrm{Fin}\,\mathrm{nRows} \times \mathrm{Fin}\,\mathrm{nCols}$.
We use the option type $\mathrm{Option}\,V$ with elements $\none$ and $\some\,v$;
missing entries are $\none$.

\section{Partial Databases, Consistency, and Gluing}

\begin{definition}[Partial database]
A \emph{partial database} is a function
$\PartialDB := \mathrm{DBPos} \to \mathrm{Option}\,V$, with domain
$\dom(db) := \{p \mid db\,p \neq \none\}$.
\end{definition}

\begin{definition}[Global section, restriction]
$db$ is a \emph{global section} if $\forall p,\ db\,p \neq \none$. For a decidable
subset $S$, the restriction $db{\restriction}S$ sends $p \mapsto db\,p$ if
$p \in S$ and to $\none$ otherwise.
\end{definition}

\begin{definition}[Consistency, sheaf condition]
$db_1, db_2$ are \emph{consistent}, $\mathrm{ConsistentPair}(db_1,db_2)$, if
\[ \forall p\,v_1\,v_2,\quad db_1\,p=\some\,v_1 \wedge db_2\,p=\some\,v_2
   \Rightarrow v_1=v_2. \]
A family $dbs:\iota\to\PartialDB$ satisfies the \emph{sheaf condition} if every
pair is consistent.
\end{definition}

\begin{definition}[Gluing]
$\Glue(db_1,db_2)\,p := \some\,v$ if $db_1\,p=\some\,v$, else $db_2\,p$.
\end{definition}

\begin{proposition}[\texttt{consistent\_pair\_refl}, \texttt{consistent\_pair\_symm}, \texttt{consistent\_with\_empty}]
Consistency is reflexive and symmetric, and the everywhere-$\none$ database is
consistent with every $db$.
\end{proposition}
\begin{proof}
Reflexivity: $\some\,v_1=\some\,v_2 \Rightarrow v_1=v_2$. Symmetry: swap the
roles of the values. Universality of the empty database: its hypothesis
$\none=\some\,v_1$ is impossible, so the implication is vacuous.
\end{proof}

\section{Gluing Theorems}

\begin{lemma}[\texttt{gluing\_extends\_left}, \texttt{gluing\_extends\_right}]
If $db_1\,p=\some\,v$ then $\Glue(db_1,db_2)\,p=\some\,v$. If $db_1\,p=\none$ then
$\Glue(db_1,db_2)\,p=db_2\,p$.
\end{lemma}

\begin{theorem}[\texttt{gluing\_extends\_both}]
If $\mathrm{ConsistentPair}(db_1,db_2)$, then $\Glue(db_1,db_2)$ extends both:
$\forall p\,v,\ db_1\,p=\some\,v \Rightarrow \Glue(db_1,db_2)\,p=\some\,v$ and
the same with $db_2$.
\end{theorem}
\begin{proof}
The first part is the left-extension lemma. For the second, case on $db_1\,p$: if
$db_1\,p=\some\,v_1$, consistency gives $v_1=v$, so the gluing returns
$\some\,v$; if $db_1\,p=\none$, the gluing returns $db_2\,p=\some\,v$.
\end{proof}

\begin{theorem}[\texttt{gluing\_increases\_domain}, \texttt{gluing\_preserves\_right\_domain}]
$\dom(db_1)\subseteq\dom(\Glue(db_1,db_2))$ and
$\dom(db_2)\subseteq\dom(\Glue(db_1,db_2))$.
\end{theorem}

\begin{theorem}[\texttt{gluing\_preserves\_consistency}]
If $\mathrm{ConsistentPair}(db_1,db_3)$ and $\mathrm{ConsistentPair}(db_2,db_3)$,
then $\mathrm{ConsistentPair}(\Glue(db_1,db_2),db_3)$.
\end{theorem}
\begin{proof}
Fix $p$ with $\Glue(db_1,db_2)\,p=\some\,v_1$ and $db_3\,p=\some\,v_2$. If
$db_1\,p=\some\,v$ then $v_1=v$ and $v=v_2$ by consistency of $db_1,db_3$; if
$db_1\,p=\none$ then $\Glue(db_1,db_2)\,p=db_2\,p=\some\,v_1$ and $v_1=v_2$ by
consistency of $db_2,db_3$.
\end{proof}

\begin{definition}[Local extension]
$\mathrm{LocallyExtends}(db_{\mathrm{ext}},db)$ holds when $db_{\mathrm{ext}}$
agrees with $db$ on $\dom(db)$ and fills at least one additional position.
\end{definition}

\begin{theorem}[\texttt{gluing\_locally\_extends\_of\_not\_contained}]
If $db_1,db_2$ are consistent and $\exists p,\ db_1\,p=\none \wedge db_2\,p\neq\none$,
then $\mathrm{LocallyExtends}(\Glue(db_1,db_2),db_1)$.
\end{theorem}

\section{The Coboundary Norm and the Bridge Theorem}

\begin{definition}[Disagreement indicator, coboundary norm]
For $V$ with decidable equality, $\mathrm{disagreementAt}(db_1,db_2,p)$ is $1$ if
both are defined at $p$ and disagree, else $0$. For
$dbs:\mathrm{Fin}\,n\to\PartialDB$,
\[ \mathrm{CoboundaryNorm}(dbs) := \sum_{i,j}\sum_{r,c}
   \mathrm{disagreementAt}(dbs\,i,\,dbs\,j,\,(r,c)). \]
\end{definition}

\begin{theorem}[\texttt{coboundary\_zero\_iff\_sheaf}]
$\mathrm{CoboundaryNorm}(dbs)=0 \iff \mathrm{SheafCondition}(dbs)$.
\end{theorem}
\begin{proof}
A finite sum of naturals is zero iff each summand is zero. Forward: peeling the
sum over $i,j,r,c$ forces every indicator to vanish, hence every overlapping pair
agrees. Backward: the sheaf condition makes every indicator zero. This is the
discrete instance of $\ker(\delta^0)=H^0=$ global sections.
\end{proof}

\begin{theorem}[\texttt{sheaf\_condition\_of\_global\_restriction}]
For any database $g$ and family $S:\iota\to\mathrm{Set}(\mathrm{DBPos})$, the
family $i \mapsto g{\restriction}(S\,i)$ satisfies the sheaf condition.
\end{theorem}
\begin{proof}
At a position defined in both restrictions, both membership tests succeed, so both
values equal $g\,p$.
\end{proof}

\section{Overlap Constraint Counting}

\begin{definition}
$\mathrm{overlapConstraintCount}(n,\mathrm{nRows},\mathrm{nCols}) :=
\frac{n(n-1)}{2}\cdot(\mathrm{nRows}\cdot\mathrm{nCols})$.
\end{definition}

\begin{proposition}[\texttt{overlap\_zero\_of\_lt\_two}, \texttt{overlap\_quadratic\_growth}]
The count is $0$ for $n<2$ and at most $n^2\cdot(\mathrm{nRows}\cdot\mathrm{nCols})$.
\end{proposition}

\section{The Sheaf Imputation Problem}

\begin{definition}[Imputation objective]
For observed data $obs$ and candidate $cand:\mathrm{DBPos}\to V$,
\[ \mathrm{SheafImputationObjective}(obs,cand) := \sum_{r,c}
   \begin{cases} [\,v\neq cand(r,c)\,] & obs(r,c)=\some\,v\\ 0 & obs(r,c)=\none.\end{cases} \]
\end{definition}

\begin{theorem}[\texttt{imputation\_zero\_iff\_extends}]
$\mathrm{SheafImputationObjective}(obs,cand)=0 \iff \forall p\,v,\ obs\,p=\some\,v
\Rightarrow cand\,p=v$.
\end{theorem}
\begin{proof}
Apply finite-sum-zero across rows and columns; the summand at $(r,c)$ vanishes
iff $obs$ is undefined there or the candidate matches, which collectively is the
extension property.
\end{proof}

\section{Sheaf Filtrations: Progressive Imputation}

\begin{definition}[Sheaf filtration]
A $\mathrm{SheafFiltration}$ of depth $d$ is a family $\mathrm{level}:\mathrm{Fin}\,d
\to\PartialDB$ with \emph{monotonicity} ($i\le j \Rightarrow$ values persist) and
\emph{consistency} ($\mathrm{SheafCondition}\,\mathrm{level}$). It is
\emph{complete} when the final level is a global section.
\end{definition}

\begin{theorem}[\texttt{sheaf\_filtration\_auto\_consistent}]
If $\mathrm{level}$ is monotone, it satisfies the sheaf condition.
\end{theorem}
\begin{proof}
For $i\le j$, monotonicity gives $\mathrm{level}\,j\,p=\some\,v_1$, forcing
$v_1=v_2$; the case $j<i$ is symmetric.
\end{proof}

\begin{theorem}[\texttt{sheaf\_filtration\_exists\_singleton}, \texttt{filtration\_final\_contains\_all}]
Any $db$ is a depth-$1$ filtration; and in any filtration of positive depth,
$\dom(\mathrm{level}\,i)\subseteq\dom(\mathrm{level}_{\,d-1})$ for all $i$.
\end{theorem}

\section{The Consistency Probability Model}

\begin{definition}
$\mathrm{consistencyProbability}(r,c) := (1-r)^c$.
\end{definition}

\begin{proposition}[\texttt{consistency\_prob\_nonneg}, \texttt{consistency\_prob\_le\_one}]
For $0\le r\le 1$ and any $c$, $0\le(1-r)^c\le 1$.
\end{proposition}

\begin{proposition}[\texttt{consistency\_prob\_mono\_constraints}, \texttt{consistency\_prob\_mono\_rate}]
$(1-r)^c$ is antitone in $c$ (for $0\le r\le 1$) and antitone in $r$ (for $r\le1$).
\end{proposition}

\begin{proposition}[\texttt{consistency\_prob\_zero\_rate}, \texttt{consistency\_prob\_one\_rate}]
$(1-0)^c=1$, and $(1-1)^c=0$ for $c>0$.
\end{proposition}

\begin{proposition}[\texttt{consistency\_prob\_mul}, \texttt{consistency\_prob\_double}]
$(1-r)^{c_1+c_2}=(1-r)^{c_1}(1-r)^{c_2}$ and $(1-r)^{2c}=\big((1-r)^c\big)^2$.
\end{proposition}

\begin{conjecture}[\texttt{conjecture\_exponential\_decay\_testable}]
For all $n,k$ and $r\in\mathbb{R}$ with $0<r<1$, $2\le n$, $1\le k$,
\[ \mathrm{consistencyProbability}\big(r,\ \mathrm{overlapConstraintCount}(n,k,n)\big)
   < \mathrm{consistencyProbability}(r,\ k\cdot n). \]
\end{conjecture}

\noindent\textbf{Numerical illustration.} With $n=10$, $k=100$, $r=0.3$ the
constraint count is $\frac{10\cdot 9}{2}\cdot 1000 = 45000$ and
$(0.7)^{45000}\approx 10^{-6968}$---operationally zero. Random tables are
essentially never globally consistent; observed consistency is a fingerprint of
genuine structure.

\section{Algorithms}
\textbf{A. Pairwise gluing}: compute $\Glue(db_1,db_2)$ cellwise,
$O(\mathrm{nRows}\cdot\mathrm{nCols})$; extends both inputs.
\textbf{B. Iterated integration}: fold $m$ pairwise-consistent sources with
$\Glue$, $O(m\cdot\mathrm{nRows}\cdot\mathrm{nCols})$; order-independent by the
preservation theorem.
\textbf{C. Inconsistency audit}: compute $\mathrm{CoboundaryNorm}$,
$O(n^2\cdot\mathrm{nRows}\cdot\mathrm{nCols})$; zero iff gluable.
\textbf{D. Sheaf imputation}: among zero-objective completions (the faithful
extensions), select one minimizing the coboundary norm over the chosen feature
subsets.

\section{Applications and Discussion}
Iterated gluing models multi-source integration with guaranteed
order-independence; the coboundary norm is a scalar inconsistency audit; the
imputation objective makes completion a verifiable optimization; sheaf
filtrations model streaming imputation with automatic consistency. The
qualitative consequence is the exponential consistency cliff: random data is
almost never globally consistent, so observed consistency signals structure, and
sheaf imputation seeks completions respecting the overlap constraints that other
methods discard.

\section{Future Directions}
(i) Upgrade partial sections to a genuine presheaf on a poset/space so
restriction is functorial. (ii) Replace boolean present/absent with graded or
weighted information so gluing reconciles rather than selects. (iii) Produce a
verified executable gluing (the choice is irrelevant under pairwise
compatibility). (iv) Develop the first cohomology of this discrete sheaf to
measure and explain irreconcilable conflicts.

\section{Conclusion}
Databases form a discrete sheaf; integration is gluing; optimal imputation is
the vanishing of an objective; inconsistency is a coboundary. The bridge theorem
\texttt{coboundary\_zero\_iff\_sheaf} realizes ``data imputation is a
sheaf-cohomology problem'' as an exact equivalence, and the consistency-probability
model supplies a falsifiable quantitative law.

\end{document}

