function COBOUNDARY_NORM(dbs, grid):
    total <- 0
    for each source a in dbs:
        for each source b in dbs:
            for each position p in grid:
                if a[p] is some v1 and b[p] is some v2 and v1 != v2:
                    total <- total + 1
    return total
# total == 0  <=>  sheaf condition holds (family is gluable)

